import{_ as s,o as t,c as n,ag as e}from"./chunks/framework.CmaAMB6e.js";const b=JSON.parse('{"title":"02 · 容量估算","description":"","frontmatter":{"概念":"容量估算","技能":"system-design","阶段":"1-方法论","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z","前置":"01 系统设计方法论","耗时":"1.5~2 小时"},"headers":[],"relativePath":"system-design/concepts/02-capacity-estimation.md","filePath":"system-design/concepts/02-capacity-estimation.md","lastUpdated":null}'),p={name:"system-design/concepts/02-capacity-estimation.md"};function l(i,a,r,d,o,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="_02-·-容量估算" tabindex="-1">02 · 容量估算 <a class="header-anchor" href="#_02-·-容量估算" aria-label="Permalink to &quot;02 · 容量估算&quot;">​</a></h1><blockquote><p><strong>前置</strong>：01 系统设计方法论 · <strong>预计</strong>：1.5~2 小时</p></blockquote><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>容量估算是在写任何代码之前，用「日活 × 行为频率」推导出系统需要扛住的 QPS、存储量和带宽的数学过程。它的目的是<strong>确定量级</strong>（千级、万级、十万级），而不是算出精确数字——精确值要靠压测，估算的作用是排除错误方案：量级决定单机够不够、要不要缓存、要不要消息队列、要不要分片。</p><p>对前端工程师来说，这相当于在写组件前先估算数据量：一张表格渲染 100 行和 100 万行，方案完全不同（虚拟滚动 vs 分页）。后端同理——QPS 100 和 QPS 10 万的系统，架构根本不是同一个东西。</p><p>估算的整套思路是<strong>自上而下</strong>：日活 → 单用户行为数 → 峰值 QPS → 存储行数 × 行大小 → 带宽。每一步都有明确的公式，但中间的假设（用户日均请求几次、峰值系数）才是真正考验业务理解的地方。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-基础指标-qps-tps-并发数" tabindex="-1">1. 基础指标：QPS / TPS / 并发数 <a class="header-anchor" href="#_1-基础指标-qps-tps-并发数" aria-label="Permalink to &quot;1. 基础指标：QPS / TPS / 并发数&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>关注点</th></tr></thead><tbody><tr><td>QPS</td><td>Queries Per Second，每秒查询数</td><td>读接口的量级</td></tr><tr><td>TPS</td><td>Transactions Per Second，每秒事务数</td><td>写接口/订单类操作的量级</td></tr><tr><td>并发数</td><td>同一时刻在途请求数</td><td>决定线程池、连接池大小</td></tr></tbody></table><p>三者关系（Little&#39;s Law 的简化版）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>并发数 = QPS × 平均响应时间</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：QPS = 2000，平均响应 50ms</span></span>
<span class="line"><span>并发数 = 2000 × 0.05 = 100 个在途请求</span></span>
<span class="line"><span>→ 数据库连接池、Web 服务器线程数只需围绕 100 来配</span></span></code></pre></div><p>这条公式常被忽略：<strong>QPS 高不一定并发高</strong>，响应快就能用少量线程扛住高 QPS。</p><h4 id="_2-从日活估算峰值-qps" tabindex="-1">2. 从日活估算峰值 QPS <a class="header-anchor" href="#_2-从日活估算峰值-qps" aria-label="Permalink to &quot;2. 从日活估算峰值 QPS&quot;">​</a></h4><p>以短链系统为例，逐步推导：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已知：</span></span>
<span class="line"><span>  日活用户 DAU        = 100 万</span></span>
<span class="line"><span>  每个用户日均访问短链 = 20 次（业务假设）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>步骤 1：日总请求量 = DAU × 人均次数 = 100万 × 20 = 2000 万次/天</span></span>
<span class="line"><span>步骤 2：日均 QPS  = 日总量 / 86400 秒 ≈ 231</span></span>
<span class="line"><span>步骤 3：峰值系数  = 流量集中（早晚高峰）取 3~5 倍</span></span>
<span class="line"><span>  峰值 QPS ≈ 231 × 4 ≈ 1000</span></span>
<span class="line"><span>结论：读接口按 1000 QPS 设计（重定向是主读路径）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>安全余量：再乘 2~3 倍冗余（活动、爬虫）</span></span>
<span class="line"><span>设计目标 ≈ 2000~3000 QPS</span></span></code></pre></div><p>关键洞察：<strong>1000 QPS 量级单机 + 缓存就能扛</strong>，不需要 Kafka、不需要分库分表——这就是估算对架构决策的意义。反过来，如果算出来是 10 万 QPS，就必须把读路径拆到缓存集群 + 多副本。</p><h4 id="_3-存储估算" tabindex="-1">3. 存储估算 <a class="header-anchor" href="#_3-存储估算" aria-label="Permalink to &quot;3. 存储估算&quot;">​</a></h4><p>公式：<code>总量 = 行数 × 行大小</code>。行数由「业务数据量 × 留存周期」决定，行大小把每个字段字节数加起来：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>短链表行大小估算：</span></span>
<span class="line"><span>  id        BIGINT   8 B</span></span>
<span class="line"><span>  code      VARCHAR(8)  ~10 B（utf8mb4 下可变长按实际算）</span></span>
<span class="line"><span>  url       VARCHAR(255) ~800 B（utf8mb4 最长 1020 B，按平均 200 B 估）</span></span>
<span class="line"><span>  用户 id    BIGINT   8 B</span></span>
<span class="line"><span>  created_at DATETIME 5 B（MySQL 5.6+ 紧凑格式）</span></span>
<span class="line"><span>  合计 ≈ 250 B，加索引与填充因子 → 按 400 B 估</span></span>
<span class="line"><span></span></span>
<span class="line"><span>行数 = 1000 万短链/年（写入 500 QPS × 30 天）× 保留 1 年 ≈ 3 亿行（含统计表）</span></span>
<span class="line"><span>总存储 = 3 亿 × 400 B ≈ 120 GB → 单机 SSD 即可，无需分片</span></span></code></pre></div><p>注意：<strong>行大小高估比低估好</strong>，因为漏掉索引（B+ 树索引约占总空间 30~50%）比多算更常见。</p><h4 id="_4-带宽计算" tabindex="-1">4. 带宽计算 <a class="header-anchor" href="#_4-带宽计算" aria-label="Permalink to &quot;4. 带宽计算&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单次重定向响应 ≈ 2 KB（302 + 头部，主要看 Set-Cookie/统计埋点）</span></span>
<span class="line"><span>读 QPS = 3000 → 出口带宽 = 3000 × 2 KB × 8 bit = 48 Mbps</span></span>
<span class="line"><span>加上写入与页面资源，按 3 倍余量 → 约 150 Mbps</span></span>
<span class="line"><span>→ 单台 1 Gbps 网卡的机器绰绰有余，但如果响应里有大图/视频，这步会反转架构</span></span></code></pre></div><p>带宽常被忽略，而它恰恰是「CDN 该不该上」的直接依据：响应体越大、命中率越高，CDN 省下的带宽成本就越显著。</p><h4 id="_5-量级感参考表-不用查资料就能判断" tabindex="-1">5. 量级感参考表（不用查资料就能判断） <a class="header-anchor" href="#_5-量级感参考表-不用查资料就能判断" aria-label="Permalink to &quot;5. 量级感参考表（不用查资料就能判断）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>组件</th><th>单机量级参考</th><th>超出的信号</th></tr></thead><tbody><tr><td>Nginx 反代</td><td>5 万 QPS 级</td><td>单机 CPU 瓶颈 → 加一层 LB</td></tr><tr><td>MySQL（主从）</td><td>读 5000~1 万 QPS、写 1000 QPS</td><td>加缓存 / 读写分离 / 分片</td></tr><tr><td>Redis</td><td>单实例 5~10 万 QPS</td><td>分片集群（先查慢命令，可能是指令问题）</td></tr><tr><td>Kafka</td><td>单分区数十万条/s（吞吐型）</td><td>分区数不够</td></tr><tr><td>单机静态资源</td><td>千兆网卡上限约 1~2 Gbps</td><td>上 CDN</td></tr></tbody></table><p>参考意义不是精确值（机器、配置差异巨大），而是<strong>建立「几百/几千/几万」的分档直觉</strong>，一档之间无需优化架构，跨档才需要。</p><h4 id="_6-估算的本质-先量级、后精算" tabindex="-1">6. 估算的本质：先量级、后精算 <a class="header-anchor" href="#_6-估算的本质-先量级、后精算" aria-label="Permalink to &quot;6. 估算的本质：先量级、后精算&quot;">​</a></h4><p>估算最大的陷阱是「假装精确」：算出 3123.7 QPS 毫无意义，因为输入的日活、人均次数、峰值系数全是假设。正确的姿势是：</p><ol><li>先粗算量级（千/万/十万），确定架构分档；</li><li>关键路径（写路径、热点读路径）单独精算，并标注假设来源；</li><li>把假设写进设计文档，等真实数据（监控）出来后回填校准。</li></ol><p>估算的价值不在数字本身，而在<strong>把「业务规模」翻译成「技术约束」</strong>，让方案评审有共同语言。</p><h4 id="_7-从峰值-qps-到机器数" tabindex="-1">7. 从峰值 QPS 到机器数 <a class="header-anchor" href="#_7-从峰值-qps-到机器数" aria-label="Permalink to &quot;7. 从峰值 QPS 到机器数&quot;">​</a></h4><p>估算的最后一公里：把 QPS 翻译成<strong>要买几台机器</strong>，否则架构评审没有落地感：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已知：峰值 QPS = 3000，单机（4 核 8G）实测能扛 800 QPS（经验值）</span></span>
<span class="line"><span>单点冗余：至少 2 台（一台挂了另一台扛住，即 N+1 原则）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>机器数 = ceil(峰值 QPS / 单机容量) + 1 台冗余</span></span>
<span class="line"><span>       = ceil(3000 / 800) + 1 = 4 + 1 = 5 台</span></span>
<span class="line"><span></span></span>
<span class="line"><span>预留扩容：按峰值 2 倍算 → 6 台 + 1 = 7 台？</span></span>
<span class="line"><span>不，机器数是成本，先上 5 台，监控 QPS 逼近 800×4 台=3200 时再扩——</span></span>
<span class="line"><span>架构上用「水平扩展」保证「随时能加机器」，而不是现在就买满</span></span></code></pre></div><p>这个环节的真正含义：<strong>估算驱动的是「可扩展的架构」而非「买够的机器」</strong>——单机容量和水平扩展能力（见 05 负载均衡）比多买几台机器重要得多。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>拿「每秒 5 万用户」这类口头描述当输入</strong>：必须换算成 QPS/存储/带宽三个维度，用户数本身不直接进公式。</li><li><strong>峰值系数拍脑袋</strong>：高峰是平时的 2 倍还是 20 倍，取决于业务（电商 618、抢票、秒杀完全不同），要问清楚再定。</li><li><strong>忘记带宽与出口流量</strong>：只算 QPS 不算响应体大小，大文件场景直接翻车。</li><li><strong>行大小只算业务字段</strong>：漏掉索引、BLOB/长文本、审计字段、软删除标记，存储低估 50% 以上。</li><li><strong>过度设计</strong>：算出 1000 QPS 却上了 Kafka + 分库分表——组件每多一层，故障与运维成本都翻倍。</li><li><strong>把估算当压测</strong>：估算永远只是假设，上线后必须用真实监控校验「假设的日活、人均次数、峰值系数」。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：按第 2 节公式完整估算「100 万 DAU 的短链系统」：日 QPS、峰值 QPS、1 年存储量、带宽，每一步写出算式。</li><li><strong>进阶</strong>：估算「日活 1000 万、人均发 3 条朋友圈」的 feed 系统：写 QPS、读 QPS（含信息流聚合）、图片存储量（假设每张 500 KB）、带宽。</li><li><strong>综合</strong>：选一个你手头真实的后端服务，用监控数据回填这套公式：实际日活、实际峰值 QPS、实际存储，对比估算误差，分析误差来源（假设错在哪一步）。</li></ol><blockquote><p>用 <code>/practice system-design 容量估算</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>性能预算（Lighthouse 设 LCP &lt; 2.5s 目标）</td><td>容量估算（设 QPS/延迟目标量级）</td></tr><tr><td>大数据量列表选虚拟滚动</td><td>数据量级决定分片/缓存/单机</td></tr><tr><td>包体积预算（bundle &lt; 200 KB 才做拆包）</td><td>存储/带宽量级分档（千/万/十万级）</td></tr><tr><td>用「用户量 × 埋点频率」估算埋点成本</td><td>DAU × 人均次数推导 QPS</td></tr><tr><td>页面缓存命中率预估（SSR 缓存收益）</td><td>缓存命中率估算（读多写多）</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://github.com/donnemartin/system-design-primer#back-of-the-envelope-estimation" target="_blank" rel="noreferrer">System Design Primer：Back-of-the-envelope 估算</a></li><li><a href="https://dataintensive.net/" target="_blank" rel="noreferrer">设计数据密集型应用（DDIA）第 1 章：Reliability, Scalability</a></li><li><a href="https://medium.com/@bellmar/all-the-best-engineering-advice-i-stole-from-non-technical-people-eb7f4ca2f7e" target="_blank" rel="noreferrer">Everything is broken：为什么估算永远是错的（扩展阅读）</a></li></ul>`,43)])])}const g=s(p,[["render",l]]);export{b as __pageData,g as default};
